const handleImageUpload = async (e) => {
  const file = e.target.files[0];
  if (!file) return;

  setImageUploading(true);

  const reader = new FileReader();
  reader.readAsDataURL(file);
  reader.onloadend = async () => {
    try {
      const res = await fetch(`${import.meta.env.VITE_API_URL}/api/imagekit/upload`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ file: reader.result, fileName: file.name, folder: '/pets' })
      });
      const data = await res.json();

      if (res.ok && data.success && data.url && data.url.startsWith("http")) {
        setNewPet(prev => ({ ...prev, image: data.url }));
      } else {
        alert(data.message || 'ImageKit did not return a valid URL. Please try again.');
      }
    } catch (err) {
      alert('Error uploading image: ' + err.message);
    } finally {
      setImageUploading(false);
    }
  };
};

